mapper.select:
 SELECT *
 FROM BUILDING
 WHERE DEL_YN = 'N'

     
       AND RENTAL_PTY_ID = #{detailSearch.rentalPtyId}
     
     
       AND BLDG_NM LIKE '%' || #{detailSearch.searchBuildingName} || '%'
     
     
       
     
     
       AND BLDG_TYPE_CODE = #{detailSearch.searchBuildingStatus}
     
     
       AND BLDG_TYPE_GROUP_CD = #{detailSearch.searchBuildingType}
     
     
       AND BLDG_CMPLTN_DT >= TO_DATE(#{detailSearch.searchBuildingRegDateFrom}, 'YYYY-MM-DD')
     
     
       AND BLDG_CMPLTN_DT <= TO_DATE(#{detailSearch.searchBuildingRegDateTo}, 'YYYY-MM-DD') + 1
     
   
 ORDER BY BLDG_CMPLTN_DT DESC

SELECT COUNT(BLDG_ID)
FROM BUILDING
WHERE DEL_YN = 'N'
  
    
      AND RENTAL_PTY_ID = #{detailSearch.rentalPtyId}
    
    
      AND BLDG_NM LIKE '%' || #{detailSearch.searchBuildingName} || '%'
    
    
      
    
    
      AND BLDG_TYPE_CODE = #{detailSearch.searchBuildingStatus}
    
    
      AND BLDG_TYPE_GROUP_CD = #{detailSearch.searchBuildingType}
    
    
      AND BLDG_CMPLTN_DT >= TO_DATE(#{detailSearch.searchBuildingRegDateFrom}, 'YYYY-MM-DD')
    
    
      AND BLDG_CMPLTN_DT <= TO_DATE(#{detailSearch.searchBuildingRegDateTo}, 'YYYY-MM-DD') + 1

